import { loadFont } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

const face = loadFont("normal", { weights: ["400"], subsets: ["latin"] });
const mono = loadMono("normal", { weights: ["500"], subsets: ["latin"] });

interface CursorFrameProps {
  /** The headline set inside the text frame. */
  title?: string;
  /** Selection colour: frame, handles and the size badge. */
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the title. Load it yourself; Geist by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Draw the mouse cursor that drags the frame. */
  showCursor?: boolean;
  /** Size of the title and frame, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

const THEMES = {
  light: { bg: "#FAFAF9", fg: "#0E0E0D", handle: "#FFFFFF" },
  dark: { bg: "#0A0A0A", fg: "#F2F2F0", handle: "#FFFFFF" },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_DRAG = Easing.bezier(0.45, 0, 0.2, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Beats, in frames at 30fps (before `speed`).
const ENTER = 0;
const ENTER_LEN = 24;
const PRESS = 25;
const DRAG = 28;
const DRAG_END = 70;
const GRAB = 80;
const RESIZE = 86;
const RESIZE_END = 134;
const RELEASE = 140;
const CLEAR = 150;
const RECENTRE = 148;
const RECENTRE_LEN = 36;
const WORD_IN = 12;
const LINE_HEIGHT = 1.1;
const WRAP_IN = 11;
/** How far a wrapping word drifts out and slides in, in em. */
const WRAP_SLIDE = 0.3;

/** Moved more than a thousandth of a pixel to or from a neighbouring frame. */
const stepping = (prev: number, now: number, next: number) =>
  Math.abs(next - now) > 1e-3 || Math.abs(now - prev) > 1e-3;

interface Metrics {
  words: number[];
  space: number;
}

interface Placed {
  x: number;
  y: number;
}

/** Greedy line breaking at a given box width. */
function breakLines(m: Metrics, boxW: number, lineH: number) {
  const pos: Placed[] = [];
  let x = 0;
  let line = 0;
  let maxW = 0;
  m.words.forEach((w, i) => {
    if (i > 0 && x + m.space + w > boxW + 0.5) {
      line++;
      x = 0;
    } else if (i > 0) {
      x += m.space;
    }
    pos.push({ x, y: line * lineH });
    x += w;
    maxW = Math.max(maxW, x);
  });
  return { pos, lines: line + 1, maxW };
}

/** The narrowest two-line box: the most balanced split of the words. */
function twoLineWidth(m: Metrics) {
  let best = Number.POSITIVE_INFINITY;
  for (let k = 1; k < m.words.length; k++) {
    const a = m.words.slice(0, k);
    const b = m.words.slice(k);
    const wa = a.reduce((s, w) => s + w, 0) + (a.length - 1) * m.space;
    const wb = b.reduce((s, w) => s + w, 0) + (b.length - 1) * m.space;
    best = Math.min(best, Math.max(wa, wb));
  }
  return best;
}

function ArrowCursor({ size }: { size: number }) {
  return (
    <svg
      viewBox="-2 -2 20 30"
      width={(size * 20) / 30}
      height={size}
      style={{ display: "block", overflow: "visible" }}
      aria-hidden
    >
      <path
        d="M0 0 L0 21.6 L5 16.9 L8.5 25.1 L12 23.6 L8.6 15.5 L15.4 15.5 Z"
        fill="#000"
        stroke="#fff"
        strokeWidth={1.7}
        strokeLinejoin="round"
        paintOrder="stroke"
      />
    </svg>
  );
}

function ResizeCursor({ size }: { size: number }) {
  return (
    <svg
      viewBox="-15 -15 30 30"
      width={size}
      height={size}
      style={{ display: "block", overflow: "visible" }}
      aria-hidden
    >
      <path
        d="M-10.5 0 L-4.6 -5.9 L-4.6 -2.1 L4.6 -2.1 L4.6 -5.9 L10.5 0 L4.6 5.9 L4.6 2.1 L-4.6 2.1 L-4.6 5.9 Z"
        transform="rotate(45)"
        fill="#000"
        stroke="#fff"
        strokeWidth={1.7}
        strokeLinejoin="round"
        paintOrder="stroke"
      />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function CursorFrameBase({
  title = "Launch videos, in code.",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = face.fontFamily,
  fontWeight = 400,
  showCursor = true,
  scale = 1,
  delay = 0,
  theme = "light",
  speed = 1,
}: CursorFrameProps) {
  const glide = useGlide();
  const frame = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width, height } = useVideoConfig();
  const t = THEMES[theme];
  const fg = ink ?? t.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? t.bg);
  const words = title.split(/\s+/).filter(Boolean);
  const u = width / 1280;

  const fontSize = Math.round(width * 0.068);
  const lineH = fontSize * LINE_HEIGHT;

  const wordRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const spaceRef = useRef<HTMLSpanElement>(null);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("cursor-frame: measuring"));
  const released = useRef(false);

  // biome-ignore lint/correctness/useExhaustiveDependencies: re-measure when the copy or size changes
  useLayoutEffect(() => {
    let live = true;
    face
      .waitUntilDone()
      .catch(() => undefined)
      .then(() =>
        document.fonts
          .load(`${fontWeight} 100px "${fontFamily}"`)
          .catch(() => undefined),
      )
      .then(() => document.fonts.ready)
      .then(() => {
        if (!live) return;
        const space = spaceRef.current;
        if (space) {
          const next: Metrics = {
            words: wordRefs.current
              .slice(0, words.length)
              .map((el) => el?.offsetWidth ?? 0),
            space: space.offsetWidth,
          };
          setMetrics((prev) =>
            prev &&
            prev.space === next.space &&
            prev.words.join() === next.words.join()
              ? prev
              : next,
          );
        }
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [title, fontSize, handle, fontFamily, fontWeight]);

  const m = metrics ?? { words: words.map(() => 0), space: 0 };
  const wide = breakLines(m, Number.POSITIVE_INFINITY, lineH);
  const W1 = wide.maxW + fontSize * 0.04;
  const W2 = twoLineWidth(m) + fontSize * 0.04;
  const H1 = lineH;
  const x0 = width / 2 - W1 / 2;
  const y0 = height / 2 - H1 / 2;

  // Box width the hand asks for at frame f (the corner follows the cursor).
  const dragX = (f: number) =>
    interpolate(f, [DRAG, DRAG_END], [0, 1], { ...clamp, easing: EASE_DRAG });
  const dragY = (f: number) =>
    interpolate(f, [DRAG, DRAG + 14], [0, 1], { ...clamp, easing: EASE_OUT });
  const boxW = (f: number) =>
    f < RESIZE
      ? W1 * dragX(f)
      : interpolate(f, [RESIZE, RESIZE_END], [W1, W2], {
          ...clamp,
          easing: EASE_IN_OUT,
        });

  // Reflow: a word that keeps its line slides to its new slot on a critically
  // damped spring. A word that wraps leaves a fading ghost drifting on at the
  // old line end and slides in fresh at the start of the next, so no two
  // words ever cross.
  const settleAt = (f: number) => {
    const start = breakLines(m, W1, lineH);
    const pos = start.pos.map((p) => ({
      ...p,
      vx: 0,
      wrap: -1e4,
      fromX: 0,
      fromY: 0,
    }));
    let h = lineH * start.lines;
    let vh = 0;
    const w = 0.6;
    const wh = 0.6;
    const end = Math.min(f, RESIZE_END + 60);
    for (let s = RESIZE; s <= end; s++) {
      const target = breakLines(m, boxW(s), lineH);
      pos.forEach((p, i) => {
        const tp = target.pos[i] ?? p;
        if (Math.abs(tp.y - p.y) > 0.5) {
          p.wrap = s;
          p.fromX = p.x;
          p.fromY = p.y;
          p.x = tp.x;
          p.y = tp.y;
          p.vx = 0;
        }
        p.vx += (tp.x - p.x) * w * w - 2 * w * p.vx;
        p.x += p.vx;
      });
      vh += (target.lines * lineH - h) * wh * wh - 2 * wh * vh;
      h += vh;
    }
    return { pos, h };
  };
  const fA = Math.floor(frame);
  const a = settleAt(fA);
  const b = settleAt(fA + 1);
  const fr = frame - fA;
  const wordPos = a.pos.map((p, i) => {
    const q = b.pos[i];
    return q && q.wrap === p.wrap ? { ...p, x: p.x + (q.x - p.x) * fr } : p;
  });
  const settledH = a.h + (b.h - a.h) * fr;

  const fw = boxW(frame);
  const fh = frame < RESIZE ? H1 * dragY(frame) : settledH;

  // The chrome rides the corner. While the corner moves, the chrome is laid
  // out where this drag lets go and the way there is a transform: layout
  // rounds a box and a baseline to whole pixels, so chrome eased by
  // `left`/`top` clicks along pixel by pixel. At rest it keeps plain layout.
  const fhAt = (f: number) => {
    if (f < RESIZE) return H1 * dragY(f);
    const lo = Math.floor(f);
    const hA = settleAt(lo).h;
    return hA + (settleAt(lo + 1).h - hA) * (f - lo);
  };
  const cornerMoving =
    stepping(boxW(frame - speed), fw, boxW(frame + speed)) ||
    stepping(fhAt(frame - speed), fh, fhAt(frame + speed));
  const anchorW = frame < RESIZE ? boxW(DRAG_END) : boxW(RESIZE_END);
  const anchorH =
    frame < RESIZE ? H1 * dragY(DRAG_END) : settleAt(RESIZE_END + 60).h;
  const chromeAt = (x: number, y: number, ax: number, ay: number) =>
    cornerMoving
      ? { left: ax, top: ay, shift: `translate(${x - ax}px, ${y - ay}px) ` }
      : { left: x, top: y, shift: "" };

  // When does the growing frame first pass each word's centre?
  const wordIn = wide.pos.map((p, i) => {
    const centre = p.x + (m.words[i] ?? 0) * 0.5;
    for (let f = DRAG; f <= DRAG_END; f++) if (boxW(f) >= centre) return f - 4;
    return DRAG_END;
  });

  // Cursor: glides in, presses, drags the corner out, swaps to the resize
  // arrows, drags the corner in, lets go and drifts off.
  const enter = interpolate(frame, [ENTER, ENTER + ENTER_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const leave = interpolate(frame, [RELEASE + 6, RELEASE + 34], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  let cx = x0;
  let cy = y0;
  if (frame < DRAG) {
    cx = interpolate(enter, [0, 1], [x0 + width * 0.16, x0]);
    cy = interpolate(enter, [0, 1], [y0 + height * 0.2, y0]);
  } else {
    cx = x0 + fw;
    cy = y0 + fh;
  }
  cx += leave * width * 0.1;
  cy += leave * height * 0.12;
  const cursorOpacity =
    interpolate(frame, [ENTER, ENTER + 8], [0, 1], clamp) *
    interpolate(frame, [RELEASE + 14, RELEASE + 34], [1, 0], clamp);
  const press =
    interpolate(frame, [PRESS, PRESS + 3], [0, 1], clamp) -
    interpolate(frame, [DRAG_END, DRAG_END + 3], [0, 1], clamp) +
    interpolate(frame, [RESIZE - 3, RESIZE], [0, 1], clamp) -
    interpolate(frame, [RESIZE_END + 4, RESIZE_END + 7], [0, 1], clamp);
  const resizeIcon =
    interpolate(frame, [GRAB, GRAB + 3], [0, 1], clamp) -
    interpolate(frame, [RELEASE, RELEASE + 3], [0, 1], clamp);
  const cursorSize = 30 * u * (1 - press * 0.06);

  // Selection chrome: appears with the drag, clears once the text is set.
  const chromeIn = interpolate(frame, [DRAG, DRAG + 4], [0, 1], clamp);
  const clear = interpolate(frame, [CLEAR, CLEAR + 14], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });
  const chrome = chromeIn * (1 - clear);
  const handlesIn = interpolate(frame, [DRAG + 2, DRAG + 12], [0, 1], {
    ...clamp,
    easing: EASE_OUT,
  });
  const handleScale = (0.5 + 0.5 * handlesIn) * (1 - clear * 0.5);

  // Once the frame is gone, the text block glides to the optical centre.
  const re = interpolate(frame, [RECENTRE, RECENTRE + RECENTRE_LEN], [0, 1], {
    ...clamp,
    easing: EASE_IN_OUT,
  });
  const finalH = breakLines(m, W2, lineH).lines * lineH;
  const shiftX = re * (W1 - W2) * 0.5;
  const shiftY = re * (H1 - finalH) * 0.5;
  const reAt = (f: number) =>
    interpolate(f, [RECENTRE, RECENTRE + RECENTRE_LEN], [0, 1], {
      ...clamp,
      easing: EASE_IN_OUT,
    });
  // The block is laid out where it lands and the glide is a transform, for
  // the same reason as the chrome above. The transform stays on before and
  // after the glide: handed to layout at rest, the text would jump to the
  // nearest pixel.
  const recentring = stepping(
    reAt(frame - speed) * Math.max(W1, H1),
    re * Math.max(W1, H1),
    reAt(frame + speed) * Math.max(W1, H1),
  );
  const endX = (W1 - W2) * 0.5;
  const endY = (H1 - finalH) * 0.5;

  const stroke = Math.max(1, 1.5 * u);
  const hs = 9 * u;
  const corners = [
    [0, 0],
    [fw, 0],
    [0, fh],
    [fw, fh],
  ];
  const badgeSize = 13 * u;
  const badge = chromeAt(fw / 2, fh + 10 * u, anchorW / 2, anchorH + 10 * u);
  const cursorAt = (f: number) => {
    const en = interpolate(f, [ENTER, ENTER + ENTER_LEN], [0, 1], {
      ...clamp,
      easing: EASE_IN_OUT,
    });
    const lv = interpolate(f, [RELEASE + 6, RELEASE + 34], [0, 1], {
      ...clamp,
      easing: EASE_IN_OUT,
    });
    const r = reAt(f);
    const x =
      f < DRAG
        ? interpolate(en, [0, 1], [x0 + width * 0.16, x0])
        : x0 + boxW(f);
    const y =
      f < DRAG
        ? interpolate(en, [0, 1], [y0 + height * 0.2, y0])
        : y0 + fhAt(f);
    return {
      x: x + lv * width * 0.1 + r * endX,
      y: y + lv * height * 0.12 + r * endY,
    };
  };
  const cursorX = cx + shiftX;
  const cursorY = cy + shiftY;
  // The cursor travels by transform too: layout would step it pixel by pixel.
  const cPrev = cursorAt(frame - speed);
  const cNext = cursorAt(frame + speed);
  const cursorMoving =
    stepping(cPrev.x, cursorX, cNext.x) || stepping(cPrev.y, cursorY, cNext.y);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {/* measuring row: never shown */}
      <div
        style={{
          position: "absolute",
          visibility: "hidden",
          whiteSpace: "pre",
          fontFamily,
          fontSize,
          fontWeight,
          letterSpacing: "-0.035em",
        }}
      >
        {words.map((w, i) => (
          <span
            key={i}
            ref={(el) => {
              wordRefs.current[i] = el;
            }}
            style={{ display: "inline-block" }}
          >
            {w}
          </span>
        ))}
        <span ref={spaceRef} style={{ display: "inline-block" }}>
          {" "}
        </span>
      </div>

      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: x0 + endX,
            top: y0 + endY,
            width: 0,
            height: 0,
            opacity: metrics ? 1 : 0,
            transform: `translate(${(1 - re) * -endX}px, ${(1 - re) * -endY}px)${glide(recentring)}`,
          }}
        >
          {words.map((w, i) => {
            const p = interpolate(
              frame,
              [wordIn[i] ?? DRAG, (wordIn[i] ?? DRAG) + WORD_IN],
              [0, 1],
              { ...clamp, easing: EASE_OUT },
            );
            const pos = wordPos[i] ?? {
              x: 0,
              y: 0,
              wrap: -1e4,
              fromX: 0,
              fromY: 0,
            };
            const wrapP = interpolate(
              frame,
              [pos.wrap + 4, pos.wrap + 4 + WRAP_IN],
              [0, 1],
              {
                ...clamp,
                easing: EASE_OUT,
              },
            );
            const ghostP = interpolate(
              frame,
              [pos.wrap, pos.wrap + WRAP_IN],
              [0, 1],
              {
                ...clamp,
                easing: EASE_OUT,
              },
            );
            const style = {
              position: "absolute",
              whiteSpace: "pre",
              fontFamily,
              fontSize,
              fontWeight,
              letterSpacing: "-0.035em",
              lineHeight: LINE_HEIGHT,
              color: fg,
            } as const;
            const inP = p * wrapP;
            const dropAt = (f: number) =>
              (1 -
                interpolate(
                  f,
                  [wordIn[i] ?? DRAG, (wordIn[i] ?? DRAG) + WORD_IN],
                  [0, 1],
                  { ...clamp, easing: EASE_OUT },
                )) *
                fontSize *
                0.12 -
              (1 -
                interpolate(f, [pos.wrap + 4, pos.wrap + 4 + WRAP_IN], [0, 1], {
                  ...clamp,
                  easing: EASE_OUT,
                })) *
                fontSize *
                0.22;
            const drop = dropAt(frame);
            const dropping = stepping(
              dropAt(frame - speed),
              drop,
              dropAt(frame + speed),
            );
            return (
              <span key={i}>
                {ghostP < 1 ? (
                  <span
                    style={{
                      ...style,
                      left: pos.fromX + ghostP * fontSize * WRAP_SLIDE,
                      top: pos.fromY,
                      opacity: 1 - ghostP,
                      filter: `blur(${ghostP * 6}px)`,
                    }}
                  >
                    {w}
                  </span>
                ) : null}
                <span
                  style={{
                    ...style,
                    left: pos.x,
                    top: pos.y,
                    opacity: inP,
                    filter: inP < 1 ? `blur(${(1 - inP) * 8}px)` : undefined,
                    transform: `translateY(${drop}px)${glide(dropping && !recentring)}`,
                  }}
                >
                  {w}
                </span>
              </span>
            );
          })}

          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: fw,
              height: fh,
              boxShadow: `inset 0 0 0 ${stroke}px ${accent}`,
              opacity: chrome,
            }}
          />
          {corners.map(([hx, hy]) => {
            const at = chromeAt(
              hx - hs / 2,
              hy - hs / 2,
              (hx === 0 ? 0 : anchorW) - hs / 2,
              (hy === 0 ? 0 : anchorH) - hs / 2,
            );
            return (
              <div
                key={`${hx === 0 ? "l" : "r"}${hy === 0 ? "t" : "b"}`}
                style={{
                  position: "absolute",
                  left: at.left,
                  top: at.top,
                  width: hs,
                  height: hs,
                  boxSizing: "border-box",
                  background: t.handle,
                  border: `${stroke}px solid ${accent}`,
                  borderRadius: 1.5 * u,
                  opacity: chrome * handlesIn,
                  transform: `${at.shift}scale(${handleScale})`,
                }}
              />
            );
          })}
          <div
            style={{
              position: "absolute",
              left: badge.left,
              top: badge.top,
              transform: `${badge.shift}translateX(-50%)${glide(cornerMoving && !recentring)}`,
              padding: `${3 * u}px ${6 * u}px`,
              borderRadius: 4 * u,
              background: accent,
              color: "#FFFFFF",
              fontFamily: mono.fontFamily,
              fontWeight: 500,
              fontSize: badgeSize,
              lineHeight: 1.2,
              letterSpacing: "0.01em",
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "pre",
              opacity: chrome * handlesIn,
            }}
          >
            {`${Math.round(fw)} × ${Math.round(fh)}`}
          </div>
        </div>

        {showCursor ? (
          <div
            style={{
              position: "absolute",
              left: cursorMoving ? x0 : cursorX,
              top: cursorMoving ? y0 : cursorY,
              transform: cursorMoving
                ? `translate(${cursorX - x0}px, ${cursorY - y0}px)`
                : undefined,
              opacity: metrics ? cursorOpacity : 0,
              filter: "drop-shadow(0 1px 1.5px rgba(0,0,0,0.28))",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                opacity: 1 - resizeIcon,
              }}
            >
              <ArrowCursor size={cursorSize} />
            </div>
            <div
              style={{
                position: "absolute",
                left: -cursorSize * 0.5,
                top: -cursorSize * 0.5,
                opacity: resizeIcon,
              }}
            >
              <ResizeCursor size={cursorSize} />
            </div>
          </div>
        ) : null}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "light",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  title: {
    type: "text-content",
    default: "Launch videos, in code.",
    description: "Title",
  },
  fontWeight: {
    type: "number",
    default: 400,
    min: 100,
    max: 900,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  showCursor: {
    type: "boolean",
    default: true,
    description: "Cursor",
  },
  fontFamily: {
    type: "font-family",
    default: "Geist",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","title","fontWeight","showCursor","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "light",
  accent: "#3B5BFD",
  title: "Launch videos, in code.",
  fontWeight: 400,
  showCursor: true,
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  speed: 1,
};

type CursorFrameElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CursorFrameBase>;

const CursorFrameInner = forwardRef<
  HTMLDivElement,
  CursorFrameElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CursorFrame>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CursorFrameBase
          {...(componentProps as unknown as ComponentProps<typeof CursorFrameBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CursorFrame = Interactive.withSchema({
  Component: CursorFrameInner,
  componentName: "<CursorFrame>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
